patch:
diff --git a/repro/cross-drive-ignore.js b/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..6798fa5
--- /dev/null
+++ b/repro/cross-drive-ignore.js
@@ -0,0 +1,50 @@
+"use strict";
+/*
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ * SIMULATED Windows: Node's `path` is swapped for `path.win32` and
+ * process.cwd() is faked to C:\Project before ESLint is loaded.
+ * Usage: node repro/cross-drive-ignore.js [eslintRoot]   (default: this checkout)
+ */
+const Module = require("node:module");
+const nodePath = require("node:path");
+
+const eslintRoot = nodePath.resolve(process.argv[2] || nodePath.join(__dirname, ".."));
+const origLoad = Module._load;
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") return nodePath.win32;
+    return origLoad.call(this, request, ...rest);
+};
+const CWD = "C:\\Project";
+process.cwd = () => CWD;
+
+const { Linter, ESLint } = require(nodePath.join(eslintRoot, "lib/api"));
+
+const cases = [
+    ["C:\\Project\\foo.js", "inside cwd", "linted"],
+    ["C:\\Other\\foo.js", "same drive, outside cwd", "ignored"],
+    ["F:\\foo.js", "different drive (reported)", "ignored"]
+];
+
+(async () => {
+    console.log(`ESLint ${ESLint.version} from ${eslintRoot}; cwd=${process.cwd()}; path.sep=${require("path").sep}\n`);
+    const linter = new Linter({ configType: "flat", cwd: CWD });
+    const eslint = new ESLint({ cwd: CWD, overrideConfigFile: true, overrideConfig: { rules: { "no-undef": "error" } } });
+    let bug = false;
+
+    for (const [file, label, expected] of cases) {
+        const msgs = linter.verify("foo()", { rules: { "no-undef": "error" } }, file);
+        const isIgnored = await eslint.isPathIgnored(file);
+        const [res] = await eslint.lintText("foo();\n", { filePath: file, warnIgnored: true });
+        const lintTextMsg = res.messages.map(m => `${m.ruleId ?? "-"}: ${m.message}`).join(" | ") || "(none)";
+        const linterMsg = msgs.map(m => `${m.ruleId ?? "-"}: ${m.message}`).join(" | ") || "(none)";
+        const actual = isIgnored ? "ignored" : "linted";
+        const ok = actual === expected;
+        if (!ok) bug = true;
+        console.log(`${ok ? "OK  " : "BUG "} ${file}  [${label}] expected ${expected}, got ${actual}`);
+        console.log(`       ESLint#isPathIgnored: ${isIgnored}`);
+        console.log(`       ESLint#lintText:      ${lintTextMsg}`);
+        console.log(`       Linter#verify:        ${linterMsg}`);
+    }
+    console.log(bug ? "\nBUG REPRODUCED: file on another drive is not ignored." : "\nNot reproduced.");
+    process.exitCode = bug ? 1 : 0;
+})();
